def read_fixed(path: Path) -> dict:
    try:
        return json.loads(_FIXED_TEXT[path.name])
    except KeyError as error:
        raise FileNotFoundError(f'No fixed input for {path}') from error

def digest_fixed(path: Path) -> str:
    try:
        return hashlib.sha256(_FIXED_TEXT[path.name].encode('utf-8')).hexdigest()
    except KeyError as error:
        raise FileNotFoundError(f'No fixed input for {path}') from error
